/**
 * Registry access: fetch the curated list from awesome-dsh-plugin.com with an
 * in-memory cache and a bundled snapshot fallback.
 *
 * Startup behavior:
 * - This module is only loaded when dshmarket exists in the profile, so a
 *   background refresh starts immediately on server startup.
 * - There is no hard download timeout. After 4 seconds the downloader checks
 *   the average speed. If the official source is too slow it switches to a
 *   mirror; if a mirror turns out to be slower than official, it switches back
 *   to official and lets that download finish.
 * - loadRegistry() always returns the bundled snapshot first when no fresh
 *   data is available, so the UI never blocks on a slow network.
 */

import { readFileSync, existsSync } from 'node:fs'
import https from 'node:https'
import zlib from 'node:zlib'
import { fileURLToPath } from 'node:url'

export interface RegistryPlugin {
  name: string
  owner: string
  url: string
  category: string
  description: Record<string, string>
  npm?: string | null
  stars?: number | null
  install: string
  added: string
}

export interface Registry {
  updated: string
  count: number
  categories: Record<string, Record<string, string>>
  plugins: RegistryPlugin[]
}

const OFFICIAL_URL = 'https://awesome-dsh-plugin.com/plugins.json'
const MIRROR_URLS = [
  'https://raw.githubusercontent.com/awesome-dsh-plugin/awesome-dsh-plugin/main/plugins.json',
  'https://cdn.jsdelivr.net/gh/awesome-dsh-plugin/awesome-dsh-plugin@main/plugins.json',
]
const TTL_MS = 60 * 60 * 1000
const SPEED_CHECK_MS = 4000
const SLOW_SPEED_BPS = 16 * 1024 // 16 KB/s

let cache: { at: number; data: Registry } | null = null
let snapshotData: Registry | null = null
let backgroundStarted = false

function snapshotPaths(): string[] {
  const here = import.meta.url
  return [
    // Client resource root: resources/registry-snapshot.json
    fileURLToPath(new URL('../../../../../../../registry-snapshot.json', here)),
    // dshmarket package data fallback
    fileURLToPath(new URL('../data/registry-snapshot.json', here)),
  ]
}

function snapshot(): Registry {
  if (snapshotData) return snapshotData
  for (const path of snapshotPaths()) {
    try {
      if (existsSync(path)) {
        snapshotData = JSON.parse(readFileSync(path, 'utf8')) as Registry
        return snapshotData
      }
    } catch {
      // Try the next snapshot location.
    }
  }
  throw new Error('registry snapshot not found')
}

function fetchUrl(
  url: string,
  options: { compareSpeed?: number | null; allowSpeedSwitch?: boolean } = {},
): Promise<Registry> {
  const {
    compareSpeed = null,
    allowSpeedSwitch = true,
  } = options

  return new Promise<Registry>((resolve, reject) => {
    let settled = false
    let received = 0
    let raw = ''
    let startedAt = Date.now()
    let speedTimer: NodeJS.Timeout | null = null
    let req: ReturnType<typeof https.get> | undefined

    const fail = (error: Error) => {
      if (settled) return
      settled = true
      if (speedTimer) clearTimeout(speedTimer)
      if (req && !req.destroyed) req.destroy()
      reject(error)
    }

    req = https.get(url, {
      family: 4,
      agent: new https.Agent({ keepAlive: false }),
      headers: {
        'Accept-Encoding': 'gzip',
        'User-Agent': 'DSH-Hub/1.0 (+https://awesome-dsh-plugin.com)',
      },
    }, (res) => {
      if (res.statusCode !== 200) {
        fail(new Error(`HTTP ${res.statusCode}`))
        res.resume()
        return
      }

      const useGzip = (res.headers['content-encoding'] || '').includes('gzip')
      const stream = useGzip ? res.pipe(zlib.createGunzip()) : res
      stream.setEncoding('utf8')

      stream.on('data', (chunk: string) => {
        received += Buffer.byteLength(chunk, 'utf8')
        raw += chunk
      })

      stream.on('end', () => {
        if (settled) return
        settled = true
        if (speedTimer) clearTimeout(speedTimer)
        try {
          const data = JSON.parse(raw) as Registry
          if (!Array.isArray(data.plugins) || data.plugins.length === 0) {
            reject(new Error('empty registry'))
            return
          }
          resolve(data)
        } catch (error) {
          reject(error instanceof Error ? error : new Error(String(error)))
        }
      })

      stream.on('error', (error) => fail(error))
    })

    req.on('error', (error) => fail(error))

    if (allowSpeedSwitch) {
      speedTimer = setTimeout(() => {
        if (settled) return
        const elapsed = (Date.now() - startedAt) / 1000
        const speed = elapsed > 0 ? received / elapsed : 0
        const tooSlow = speed < SLOW_SPEED_BPS
        const slowerThanOfficial = compareSpeed != null && speed <= compareSpeed
        if (tooSlow || slowerThanOfficial) {
          const error = new Error('slow source') as Error & { speed?: number; source?: string }
          error.speed = speed
          error.source = url
          fail(error)
        }
      }, SPEED_CHECK_MS)
    }
  })
}

async function downloadRegistry(): Promise<Registry> {
  let officialSpeed: number | null = null
  let lastError: Error | null = null

  // Try official first with speed-based switching.
  try {
    return await fetchUrl(OFFICIAL_URL, { allowSpeedSwitch: true })
  } catch (error) {
    const err = error instanceof Error ? error : new Error(String(error))
    officialSpeed = typeof (err as Error & { speed?: unknown }).speed === 'number'
      ? (err as Error & { speed: number }).speed
      : null
    lastError = err
  }

  // Try mirrors. If a mirror is slower than official, go back to official.
  for (const mirror of MIRROR_URLS) {
    try {
      return await fetchUrl(mirror, { compareSpeed: officialSpeed, allowSpeedSwitch: true })
    } catch (error) {
      const err = error instanceof Error ? error : new Error(String(error))
      const mirrorSpeed = typeof (err as Error & { speed?: unknown }).speed === 'number'
        ? (err as Error & { speed: number }).speed
        : null
      lastError = err

      if (officialSpeed != null && mirrorSpeed != null && mirrorSpeed <= officialSpeed) {
        try {
          // Official was better; let it finish without speed-based switching.
          return await fetchUrl(OFFICIAL_URL, { allowSpeedSwitch: false })
        } catch (error2) {
          lastError = error2 instanceof Error ? error2 : new Error(String(error2))
        }
      }
    }
  }

  // If every source was too slow, still prefer official and let it finish.
  try {
    return await fetchUrl(OFFICIAL_URL, { allowSpeedSwitch: false })
  } catch (error) {
    lastError = error instanceof Error ? error : new Error(String(error))
  }

  throw lastError ?? new Error('all registry sources failed')
}

function startBackgroundRefresh(): void {
  if (backgroundStarted) return
  backgroundStarted = true

  void (async () => {
    try {
      const data = await downloadRegistry()
      if (Array.isArray(data.plugins) && data.plugins.length > 0) {
        cache = { at: Date.now(), data }
      }
    } catch {
      // Keep using the bundled snapshot.
    }
  })()
}

// The module is only loaded when dshmarket exists in the profile, so this is
// effectively "start downloading from DSH Hub startup when the market exists".
startBackgroundRefresh()

export async function loadRegistry(): Promise<{ registry: Registry; source: 'live' | 'cache' | 'snapshot' }> {
  if (cache && Date.now() - cache.at < TTL_MS) {
    return { registry: cache.data, source: 'cache' }
  }

  // Prefer the bundled snapshot until a fresh download finishes.
  const fallback = cache?.data ?? snapshot()
  startBackgroundRefresh()
  return { registry: fallback, source: cache ? 'cache' : 'snapshot' }
}
